patterns = [b'SHOPIFY_API_SECRET', b'api_secret', b'API_SECRET', b'shopify']
text_exts = {'.env','.toml','.json','.yml','.yaml','.ini','.cfg','.txt','.md','.py','.js','.ts','.tsx'}
found=[]
for base in ['/work','/inputs']:
    for root, dirs, files in os.walk(base):
        for f in files:
            path = os.path.join(root,f)
            if pathlib.Path(f).suffix.lower() in text_exts or f.startswith('.env'):
                try:
                    b = pathlib.Path(path).read_bytes()
                except Exception:
                    continue
                if any(pat in b for pat in patterns):
                    found.append(path)
print('\npossible files containing patterns:')
for p in found:
    print(p)
